plugins {
    id 'java'
    id 'org.springframework.boot' version '3.5.16'
}

group = 'com.example'
version = '0.1.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation platform('org.springframework.boot:spring-boot-dependencies:3.5.16')
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-jdbc'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'com.h2database:h2'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}

tasks.named('test') {
    useJUnitPlatform()
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

tasks.named('bootJar') {
    archiveFileName = 'app.jar'
}

tasks.named('jar') {
    enabled = false
}
rootProject.name = 'gitcangku1'
org.gradle.caching=true
org.gradle.jvmargs=-Xmx1g -Dfile.encoding=UTF-8
org.gradle.daemon=false
spring:
  application:
    name: gitcangku1
  config:
    import: "optional:configtree:/run/secrets/"
  datasource:
    # 榛樿浣跨敤宓屽叆寮?H2 鍐呭瓨搴擄紙MySQL 鍏煎妯″紡锛夛紝鏃犻渶澶栭儴鏁版嵁搴擄紱
    # 鍙€氳繃 DB_URL / DB_USER / DB_PASSWORD 鐜鍙橀噺瑕嗙洊涓哄叾浠?JDBC 鏁版嵁婧愩€?    url: ${DB_URL:jdbc:h2:mem:rail_local;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1}
    username: ${DB_USER:sa}
    password: ${DB_PASSWORD:}
    hikari:
      maximum-pool-size: 5
      minimum-idle: 1
      connection-timeout: 10000
      validation-timeout: 3000
  jackson:
    time-zone: Asia/Shanghai
  sql:
    init:
      mode: always
  lifecycle:
    timeout-per-shutdown-phase: 20s

server:
  port: 8080
  shutdown: graceful
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health
  endpoint:
    health:
      show-details: never
-- 閾佽矾璧板粖鏃ヨ鍒掓寔涔呭寲缁撴瀯锛圚2 鍐呭瓨搴擄紝MODE=MySQL 鍏煎妯″紡锛夈€?-- 鎵€鏈夋椂鍒诲瓧娈靛潎涓?UTC 姣鏃堕棿鎴筹紙epoch millis锛屾椂鍖烘棤鍏筹級锛涜繍钀ユ棩鏈熸寜 Asia/Shanghai 瑙ｉ噴銆?
CREATE TABLE IF NOT EXISTS rail_day_plan (
    id BIGINT NOT NULL AUTO_INCREMENT,
    schedule_key VARCHAR(64) NOT NULL,
    op_date DATE NOT NULL,
    version INT NOT NULL,
    status VARCHAR(16) NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_day_plan_schedule_key UNIQUE (schedule_key)
);
COMMENT ON TABLE rail_day_plan IS '閾佽矾璧板粖鏃ヨ鍒掍富琛?;
COMMENT ON COLUMN rail_day_plan.id IS '涓婚敭';
COMMENT ON COLUMN rail_day_plan.schedule_key IS '璁″垝涓氬姟閿紝鍏ㄥ眬鍞竴锛屽彇娑堝悗浠嶄繚鐣欏巻鍙?;
COMMENT ON COLUMN rail_day_plan.op_date IS '杩愯惀鏃ユ湡锛圓sia/Shanghai 鏃ュ巻鏃ワ級';
COMMENT ON COLUMN rail_day_plan.version IS '璁″垝鐗堟湰锛岃崏绋垮崰鐢ㄦ暣浣撴浛鎹㈡垚鍔熶竴娆″姞涓€';
COMMENT ON COLUMN rail_day_plan.status IS '璁″垝鐘舵€侊細DRAFT 鑽夌 / PUBLISHED 宸插彂甯?/ CANCELLED 宸插彇娑?;
COMMENT ON COLUMN rail_day_plan.created_at IS '鍒涘缓鏃跺埢锛孶TC 姣';
COMMENT ON COLUMN rail_day_plan.updated_at IS '鏈€杩戝彉鏇存椂鍒伙紝UTC 姣';

CREATE TABLE IF NOT EXISTS rail_plan_occupancy (
    id BIGINT NOT NULL AUTO_INCREMENT,
    plan_id BIGINT NOT NULL,
    seq INT NOT NULL,
    train_no VARCHAR(64) NOT NULL,
    section_id VARCHAR(64) NOT NULL,
    start_utc BIGINT NOT NULL,
    end_utc BIGINT NOT NULL,
    PRIMARY KEY (id)
);
COMMENT ON TABLE rail_plan_occupancy IS '璁″垝鍖烘鍗犵敤鏄庣粏锛屽尯闂村乏闂彸寮€锛涘彇娑堣鍒掑悗鍘嗗彶鍗犵敤淇濈暀涓嶅垹闄?;
COMMENT ON COLUMN rail_plan_occupancy.id IS '涓婚敭';
COMMENT ON COLUMN rail_plan_occupancy.plan_id IS '鎵€灞炶鍒?id锛屽叧鑱?rail_day_plan.id';
COMMENT ON COLUMN rail_plan_occupancy.seq IS '鍗犵敤鍦ㄨ鍒掑唴鐨勫簭鍙凤紝浠?0 寮€濮嬶紝淇濇寔鎻愪氦椤哄簭';
COMMENT ON COLUMN rail_plan_occupancy.train_no IS '鍒楄溅缂栧彿';
COMMENT ON COLUMN rail_plan_occupancy.section_id IS '鍖烘 ID';
COMMENT ON COLUMN rail_plan_occupancy.start_utc IS '鍗犵敤寮€濮嬫椂鍒伙紙鍚級锛孶TC 姣';
COMMENT ON COLUMN rail_plan_occupancy.end_utc IS '鍗犵敤缁撴潫鏃跺埢锛堜笉鍚級锛孶TC 姣锛屽繀椤诲ぇ浜?start_utc';
