                            "鏂版棫璁″垝杩愯惀鏃ュ繀椤荤浉鍚? 鏃?" + oldPlan.opDate() + " 鏂?" + newPlan.opDate());
                }
                if (planRepo.findLinkByPredecessor(oldPlan.id()).isPresent()) {
                    throw conflict("LINK_CONFLICT", "鏃ц鍒掑凡瀛樺湪鐩存帴鍚庣户: " + oldScheduleKey);
                }
                if (planRepo.findLinkBySuccessor(newPlan.id()).isPresent()) {
                    throw conflict("LINK_CONFLICT", "鏂拌鍒掑凡瀛樺湪鐩存帴鍓嶉┍: " + req.newScheduleKey());
