        assertThat(body.get("status").asText()).isEqualTo("CANCELLED");
        assertThat(body.get("occupancies")).hasSize(1);

        // 鏃堕殭宸查噴鏀撅細鏌ヨ涓虹┖锛屼笖鏂拌鍒掑彲鍙戝竷閲嶅彔鍖洪棿
